import { MeshBasicNodeMaterial } from 'three/webgpu';
import { Group, PlaneGeometry, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Calculate aspect ratio from atlas region (width=512, height=320)
  const aspect = 512 / 320;

  // Create plane geometry with correct ratio
  const geometry = new PlaneGeometry(aspect, 1);

  // Create material with placeholder color until texture loads
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10', // surface color as fallback
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture and set as map when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // No UV offset needed if the entire image is the source rect
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  // No event handlers since no interactions
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  return group;
}
